await measureLifecycle('database.quick-check', async () => {
  let healthy = false;
  if (!isBunRuntime()) {
    try {
      healthy = await this.checkIntegrityInWorker();
    } catch {
      // Unsupported workers retain the synchronous safety check.
    }
  }
  if (this.db !== db || healthy) return;

}

private async checkIntegrityInWorker(): Promise<boolean> {
  const require = createRequire(import.meta.url);
  const worker = new Worker(`
    const { parentPort, workerData } = require('node:worker_threads');
    let db;
    let healthy = false;
    try {
      const Database = require(workerData.nativeModule);
      db = new Database(workerData.dbPath, {
        readonly: true, fileMustExist: true, timeout: workerData.timeout,
      });
      const rows = db.prepare('PRAGMA quick_check').all();
      healthy = rows.length > 0 && rows.every(row =>
        String(Object.values(row)[0] ?? '').toLowerCase() === 'ok');
    } catch {
      healthy = false;
    } finally {
      if (db) {
        try { db.close(); } catch { healthy = false; }
      }
    }
    parentPort.postMessage(healthy);
  `, {
    eval: true,
    workerData: {
      nativeModule: require.resolve('better-sqlite3'),
      dbPath: this.dbPath,
      timeout: SQLITE_BUSY_TIMEOUT_MS,
    },
  });
  this.startupIntegrityWorker = worker;
  try {
    return await new Promise<boolean>((resolve) => {
      let healthy = false;
      worker.once('message', (result) => { healthy = result === true; });
      worker.once('error', () => { healthy = false; });
      worker.once('exit', (code) => resolve(code === 0 && healthy));
    });
  } finally {
    if (this.startupIntegrityWorker === worker) this.startupIntegrityWorker = null;
  }

const worker = this.startupIntegrityWorker;
this.startupIntegrityWorker = null;
if (worker) void worker.terminate().catch(() => {});
